describe('File Upload Feature', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/upload');
  });

  it('should successfully upload a small text file and display confirmation', () => {
    const fileName = 'test-file.txt';

    cy.get('#file-upload').selectFile({
      contents: Cypress.Buffer.from('This is a test file for upload'),
      fileName: fileName,
      mimeType: 'text/plain'
    });

    cy.get('#file-submit').click();

    cy.get('h1').should('contain', 'File Uploaded!');
    cy.get('#uploaded-files').should('contain', fileName);
  });

  it('should handle uploading a file with special characters in filename', () => {
    const fileName = 'test-file-special_chars-123.txt';

    cy.get('#file-upload').selectFile({
      contents: Cypress.Buffer.from('Content with special filename'),
      fileName: fileName,
      mimeType: 'text/plain'
    });

    cy.get('#file-submit').click();

    cy.get('h1').should('be.visible').and('contain', 'File Uploaded!');
    cy.get('#uploaded-files').should('be.visible').and('contain', fileName);
  });

  it('should display uploaded filename exactly as provided', () => {
    const fileName = 'document.txt';
    const fileContent = 'Sample document content for verification';

    cy.get('#file-upload').selectFile({
      contents: Cypress.Buffer.from(fileContent),
      fileName: fileName,
      mimeType: 'text/plain'
    });

    cy.get('#file-submit').click();

    cy.get('#uploaded-files').invoke('text').then((text) => {
      expect(text).to.include(fileName);
    });
  });

  it('should maintain file upload state and display after navigation', () => {
    const fileName = 'persistent-file.txt';

    cy.get('#file-upload').selectFile({
      contents: Cypress.Buffer.from('Persistent file content'),
      fileName: fileName,
      mimeType: 'text/plain'
    });

    cy.get('#file-submit').click();

    cy.get('#uploaded-files').should('exist').and('contain', fileName);
    cy.url().should('include', '/upload_complete');
  });
});
